static int cac_cac1_get_certificate(sc_card_t *card, u8 **out_buf, size_t *out_len)
{
    u8 buf[CAC_MAX_SIZE];  // 4096 bytes on stack
    u8 *out_ptr;
    size_t size = 0;
    size_t left = 0;
    size_t len, next_len;
    sc_apdu_t apdu;
    int r = SC_SUCCESS;

    size = left = *out_buf ? *out_len : sizeof(buf);  // left = 4096
    out_ptr = *out_buf ? *out_buf : buf;  // out_ptr = buf (stack)

    sc_format_apdu(card, &apdu, SC_APDU_CASE_2_SHORT, CAC_INS_GET_CERTIFICATE, 0, 0);
    next_len = MIN(left, 100);  // next_len = 100

    for (; left > 0; left -= len, out_ptr += len) {
        len = next_len;  // len = 100
        apdu.resp = out_ptr;  // points into buf
        apdu.le = len;  // le = 100
        apdu.resplen = left;  // resplen = 4096 (or whatever left is)

        r = sc_transmit_apdu(card, &apdu);
        // In the fuzz reader, this calls fuzz_reader_transmit
        // which sets apdu->resplen to chunk_size (capped by remaining input)
        // and copies chunk data to apdu->resp (which is out_ptr/buf)

        // The fuzz reader can write up to remaining input bytes to buf!
        // If the chunk is large (e.g., 5000 bytes), it overflows buf (4096 bytes)

        if (r < 0) break;
        if (apdu.resplen == 0) { r = SC_ERROR_INTERNAL; break; }

        if (apdu.sw1 != 0x63 || apdu.sw2 < 1) {
            r = sc_check_sw(card, apdu.sw1, apdu.sw2);
            left -= len;  // double decrement bug
            break;
        }
        next_len = MIN(left, apdu.sw2);
    }

    r = size - left;
    if (*out_buf == NULL) {
        *out_buf = malloc(r);
        memcpy(*out_buf, buf, r);  // copies r bytes from buf
    }
    *out_len = r;
}
```

The key issue: `apdu.resplen = left` is set to the full remaining buffer size (4096 on first iteration), but `apdu.le = len` is only 100. The fuzz reader ignores `le` and writes whatever chunk size it has to `apdu->resp`, up to `apdu->resplen` (which is `left` = 4096).

So if the fuzz input provides a chunk with more than 4096 bytes of data, it will overflow the stack buffer `buf`.

